{"explanation":"For a quadratic ax² + bx + c = 0 (a ≠ 0), the quadratic formula contains √(b² − 4ac). A positive discriminant gives two distinct real roots, zero gives one repeated real root, and a negative discriminant gives no real roots. Drag the parabola’s vertex to see its intersections with the x-axis change; this example keeps a = 1 while b and c update.","manimCode":"const title = new Text({ text: 'The discriminant counts real roots', fontSize: 30, color: WHITE });
title.moveTo([0, 3.3, 0]);
const equation = new Text({ text: '', fontSize: 25, color: WHITE });
equation.moveTo([0, 2.8, 0]);
const ax = new Axes({ xRange: [-2, 2, 0.5], yRange: [-3, 8, 1], xLength: 8.4, yLength: 4.6, tips: false });
let h = 0;
let k = -1;
const f = x => (x - h) * (x - h) + k;
const curve = ax.plot(f, { color: BLUE });
const vertex = new Dot({ point: ax.c2p(h, k), radius: 0.14, color: YELLOW });
const rootLeft = new Dot({ point: ax.c2p(-1, 0), radius: 0.11, color: GREEN });
const rootRight = new Dot({ point: ax.c2p(1, 0), radius: 0.11, color: GREEN });
const guide = new DashedLine({ start: ax.c2p(h, k), end: ax.c2p(h, 0), color: GRAY });
const axisLabel = new Text({ text: 'x', fontSize: 22, color: GRAY });
axisLabel.moveTo([4.5, ax.c2p(0, 0)[1], 0]);
const result = new Text({ text: '', fontSize: 24, color: GREEN });
result.moveTo([0, -2.75, 0]);
const rootsReadout = new Text({ text: '', fontSize: 21, color: WHITE });
rootsReadout.moveTo([0, -3.1, 0]);
const hint = new Text({ text: 'Drag the yellow vertex · near the x-axis it snaps to a repeated root', fontSize: 18, color: GRAY });
hint.moveTo([0, -3.5, 0]);
scene.add(title, equation, ax, axisLabel, guide, curve, rootLeft, rootRight, vertex, result, rootsReadout, hint);

function update() {
  const b = -2 * h;
  const c = h * h + k;
  const discriminant = b * b - 4 * c;
  const tone = k < 0 ? GREEN : k === 0 ? YELLOW : RED;
  curve.setFunction(f);
  vertex.moveTo(ax.c2p(h, k));
  guide.setStart(ax.c2p(h, k));
  guide.setEnd(ax.c2p(h, 0));
  guide.setOpacity(k === 0 ? 0 : 0.6);
  const signed = v => (v < 0 ? ' − ' : ' + ') + Math.abs(v).toFixed(2);
  equation.setText('y = x²' + signed(b) + 'x' + signed(c) + '     (a = 1)');
  result.setColor(tone);
  if (k < 0) {
    const offset = Math.sqrt(-k);
    rootLeft.moveTo(ax.c2p(h - offset, 0));
    rootRight.moveTo(ax.c2p(h + offset, 0));
    rootLeft.setColor(GREEN);
    rootRight.setColor(GREEN);
    rootLeft.setOpacity(1);
    rootRight.setOpacity(1);
    result.setText('Δ = b² − 4ac = ' + discriminant.toFixed(2) + ' > 0: two real roots');
    rootsReadout.setText('x = ' + (h - offset).toFixed(2) + '   and   x = ' + (h + offset).toFixed(2));
  } else if (k === 0) {
    rootLeft.moveTo(ax.c2p(h, 0));
    rootLeft.setColor(YELLOW);
    rootLeft.setOpacity(1);
    rootRight.setOpacity(0);
    result.setText('Δ = b² − 4ac = 0: one repeated real root');
    rootsReadout.setText('x = ' + h.toFixed(2) + '   ·   the parabola just touches the x-axis');
  } else {
    rootLeft.setOpacity(0);
    rootRight.setOpacity(0);
    result.setText('Δ = b² − 4ac = ' + discriminant.toFixed(2) + ' < 0: no real roots');
    rootsReadout.setText('The parabola stays above the x-axis');
  }
}
update();
makeDraggable(vertex, scene, { onDrag: (mob, pos) => {
  const coords = ax.pointToCoords(pos);
  h = Math.max(-0.5, Math.min(0.5, coords[0]));
  k = Math.max(-1.5, Math.min(1.5, coords[1]));
  if (Math.abs(k) < 0.16) k = 0;
  update();
} });
await scene.wait(999999);"}

